class ElementDefaultsNode(PlotlyNode):
    def __init__(self, array_node, plotly_schema):
        """
        Create node that represents element defaults properties
        (e.g. layout.annotationdefaults).  Construct as a wrapper around the
        corresponding array property node (e.g. layout.annotations)

        Parameters
        ----------
        array_node: PlotlyNode
        """
        super().__init__(
            plotly_schema, node_path=array_node.node_path, parent=array_node.parent
        )

        assert array_node.is_array
        self.array_node = array_node
        self.element_node = array_node.children[0].children[0]

    @property
    def node_data(self):
        return {}

    @property
    def description(self):
        array_property_path = self.parent_path_str + "." + self.array_node.name_property

        if isinstance(self.array_node, TraceNode):
            data_path = "data."
        else:
            data_path = ""

        defaults_property_path = (
            "layout.template."
            + data_path
            + self.parent_path_str
            + "."
            + self.plotly_name
        )
        return f"""\
When used in a template
(as {defaults_property_path}),
sets the default property values to use for elements
of {array_property_path}"""

    @property
    def name_base_datatype(self):
        return self.element_node.name_base_datatype

    @property
    def root_name(self):
        return self.array_node.root_name

    @property
    def plotly_name(self):
        return self.element_node.plotly_name + "defaults"

    @property
    def name_datatype_class(self):
        return self.element_node.name_datatype_class


class MappedPropNode(PlotlyNode):
    def __init__(self, mapped_prop_node, parent, prop_name, plotly_schema):
        """
        Create node that represents a legacy title property.
        e.g. layout.title_font.  These properties are now subproperties under
        the sibling `title` property. e.g. layout.title.font.

        Parameters
        ----------
        title_node: PlotlyNode
        prop_name: str
            The name of the propery (without the title prefix)
            e.g. 'font' to represent the layout.title_font property.
        """
        node_path = parent.node_path + (prop_name,)
        super().__init__(plotly_schema, node_path=node_path, parent=parent)

        self.mapped_prop_node = mapped_prop_node
        self.prop_name = prop_name

    @property
    def node_data(self):
        return {}

    @property
    def description(self):
        res = (
            f"""\
Deprecated: Please use {self.mapped_prop_node.path_str} instead.
"""
            + self.mapped_prop_node.description
        )
        return res

    @property
    def name_base_datatype(self):
        return self.mapped_prop_node.description

    @property
    def root_name(self):
        return self.parent.root_name

    @property
    def plotly_name(self):
        return self.prop_name

    @property
    def name_datatype_class(self):
        return self.mapped_prop_node.name_datatype_class

    @property
    def is_mapped(self):
        return True

    @property
    def datatype(self):
        return self.mapped_prop_node.datatype

    def get_validator_instance(self):
        return self.mapped_prop_node.get_validator_instance()

    @property
    def relative_path(self):
        return (
            self.mapped_prop_node.parent.plotly_name,
            self.mapped_prop_node.plotly_name,
        )

