import builtins

import narwhals.stable.v1 as nw
import numpy as np
import pandas as pd
import pytest

from plotly.express._core import process_args_into_dataframe
from plotly.express._special_inputs import Constant, Range


def _wrap(data):
    """Create the eager Narwhals DataFrame expected by the function."""
    return nw.from_native(pd.DataFrame(data), eager_only=True)


def _process(
    args,
    *,
    wide_mode=False,
    var_name=None,
    value_name=None,
    is_pd_like=True,
    native_namespace=pd,
):
    return process_args_into_dataframe(
        args,
        wide_mode,
        var_name,
        value_name,
        is_pd_like,
        native_namespace,
    )


def test_list_like_arguments_without_dataframe_are_materialized():
    args = {
        "data_frame": None,
        "x": [1, 2, 3],
        "y": np.array([4, 5, 6]),
        "text": ("a", "b", "c"),
    }

    result, wide_id_vars = _process(
        args, is_pd_like=False, native_namespace=None
    )

    native = result.to_native()
    assert isinstance(native, pd.DataFrame)
    assert list(native.columns) == ["x", "y", "text"]
    assert native["x"].tolist() == [1, 2, 3]
    assert native["y"].tolist() == [4, 5, 6]
    assert native["text"].tolist() == ["a", "b", "c"]
    assert args == {
        "data_frame": None,
        "x": "x",
        "y": "y",
        "text": "text",
    }
    assert wide_id_vars == {"x", "y", "text"}


def test_dataframe_columns_and_inline_sequences_are_combined():
    input_frame = _wrap({"x": [10, 20], "y": [1, 2]})
    args = {
        "data_frame": input_frame,
        "x": "x",
        "y": "y",
        "color": [100, 200],
    }

    result, wide_id_vars = _process(args)

    native = result.to_native()
    assert list(native.columns) == ["x", "y", "color"]
    assert native["x"].tolist() == [10, 20]
    assert native["y"].tolist() == [1, 2]
    assert native["color"].tolist() == [100, 200]
    assert args["x"] == "x"
    assert args["y"] == "y"
    assert args["color"] == "color"
    assert wide_id_vars == {"x", "y", "color"}
    # The input frame is only read from; its columns and values are unchanged.
    assert list(input_frame.columns) == ["x", "y"]
    assert input_frame.to_native()["x"].tolist() == [10, 20]


def test_string_argument_without_dataframe_raises_value_error():
    args = {"data_frame": None, "x": "some_column"}

    with pytest.raises(
        ValueError,
        match="String or int arguments are only possible when a DataFrame",
    ):
        _process(args, is_pd_like=False, native_namespace=None)


def test_unknown_dataframe_column_raises_value_error():
    args = {"data_frame": _wrap({"x": [1, 2]}), "x": "not_a_column"}

    with pytest.raises(ValueError) as excinfo:
        _process(args)

    message = str(excinfo.value)
    assert "Value of 'x' is not the name of a column in 'data_frame'." in message
    assert "Expected one of ['x']" in message
    assert "but received: not_a_column" in message


def test_special_index_error_includes_index_hint():
    args = {"data_frame": _wrap({"x": [1, 2]}), "x": "index"}

    with pytest.raises(ValueError) as excinfo:
        _process(args)

    message = str(excinfo.value)
    assert "but received: index" in message
    assert "To use the index, pass it in directly as `df.index`." in message


def test_sequence_argument_length_mismatch_raises_value_error():
    args = {
        "data_frame": _wrap({"x": [1, 2]}),
        "x": [1, 2],
        "y": [10],
    }

    with pytest.raises(
        ValueError,
        match=r"length of argument `y` is 1.*previously-processed arguments \['x'\] is 2",
    ):
        _process(args)


def test_dataframe_column_length_mismatch_raises_value_error():
    args = {
        "data_frame": _wrap({"x": [1, 2, 3], "y": [4, 5, 6]}),
        "x": [1, 2],
        "y": "y",
    }

    with pytest.raises(
        ValueError,
        match=r"length of column argument `df\[y\]` is 3.*previously-processed arguments \['x'\] is 2",
    ):
        _process(args)


def test_array_attrable_length_mismatch_raises_value_error():
    args = {
        "data_frame": _wrap({"x": [1, 2]}),
        "x": "x",
        "custom_data": [[1], [2, 3]],
    }

    with pytest.raises(
        ValueError,
        match=r"length of argument `custom_data_0` is 1.*previously-processed arguments \['x'\] is 2",
    ):
        _process(args)


def test_inline_hover_data_length_mismatch_raises_value_error():
    args = {
        "data_frame": _wrap({"x": [1, 2]}),
        "x": "x",
        "hover_data": {"inline": [10]},
    }

    with pytest.raises(
        ValueError,
        match=r"length of hover_data key `inline` is 1.*previously-processed arguments \['x'\] is 2",
    ):
        _process(args)


def test_constants_and_ranges_are_broadcast_to_the_existing_length():
    args = {
        "data_frame": _wrap({"x": [10, 20, 30]}),
        "x": "x",
        "y": Constant(5),
        "text": Range(label="position"),
    }

    result, wide_id_vars = _process(args)

    native = result.to_native()
    assert native["x"].tolist() == [10, 20, 30]
    assert native["y"].tolist() == [5, 5, 5]
    assert native["position"].tolist() == [0, 1, 2]
    assert args["x"] == "x"
    assert args["y"] == "y"
    assert args["text"] == "position"
    assert wide_id_vars == {"x", "y", "position"}


def test_constant_label_conflicting_with_input_column_is_rejected():
    args = {
        "data_frame": _wrap({"foo": [1, 2]}),
        "x": "foo",
        "y": Constant(3, label="foo"),
    }

    with pytest.raises(
        NameError,
        match="A column or index with name 'foo' is ambiguous",
    ):
        _process(args)


def test_array_attrables_are_resolved_item_by_item_in_place():
    input_frame = _wrap({"x": [1, 2], "y": [3, 4]})
    args = {
        "data_frame": input_frame,
        "x": "x",
        "custom_data": ["x", [7, 8]],
        "hover_data": ["y", [9, 10]],
    }

    result, wide_id_vars = _process(args)

    native = result.to_native()
    assert list(native.columns) == ["x", "custom_data_1", "hover_data_1"]
    assert native["x"].tolist() == [1, 2]
    assert native["custom_data_1"].tolist() == [7, 8]
    assert native["hover_data_1"].tolist() == [9, 10]
    assert args["custom_data"] == ["x", "custom_data_1"]
    assert args["hover_data"] == ["y", "hover_data_1"]
    assert wide_id_vars == {"x", "custom_data_1", "hover_data_1"}


def test_hover_data_dictionary_inline_data_and_conversion_side_effects():
    args = {
        "data_frame": _wrap({"x": [1, 2], "y": [3, 4]}),
        "x": "x",
        "hover_data": {
            "inline": [10, 20],
            "formatted": (".1f", [1.5, 2.5]),
            "y": True,
        },
    }

    result, wide_id_vars = _process(args)

    native = result.to_native()
    assert list(native.columns) == ["x", "inline", "formatted", "y"]
    assert native["x"].tolist() == [1, 2]
    assert native["inline"].tolist() == [10, 20]
    assert native["formatted"].tolist() == [1.5, 2.5]
    assert native["y"].tolist() == [3, 4]
    # hover_data values are normalized to (format, data) tuples in place.
    assert args["hover_data"] == {
        "inline": (True, [10, 20]),
        "formatted": (".1f", [1.5, 2.5]),
        "y": (True, None),
    }
    assert wide_id_vars == {"x", "inline", "formatted", "y"}


def test_hover_data_dictionary_data_column_conflict_raises():
    args = {
        "data_frame": _wrap({"x": [1, 2], "y": [3, 4]}),
        "x": "x",
        "hover_data": {"y": [5, 6]},
    }

    with pytest.raises(
        ValueError,
        match="Ambiguous input: values for 'y' appear both in hover_data and data_frame",
    ):
        _process(args)


def test_empty_hover_data_dictionary_is_a_noop():
    args = {
        "data_frame": _wrap({"x": [1, 2]}),
        "x": "x",
        "hover_data": {},
    }

    result, wide_id_vars = _process(args)

    assert list(result.to_native().columns) == ["x"]
    assert args["hover_data"] == {}
    assert wide_id_vars == {"x"}


def test_dimensions_none_uses_all_dataframe_columns():
    args = {
        "data_frame": _wrap({"x": [1, 2], "y": [3, 4], "z": [5, 6]}),
        "dimensions": None,
    }

    result, wide_id_vars = _process(args)

    native = result.to_native()
    assert list(native.columns) == ["x", "y", "z"]
    assert native["x"].tolist() == [1, 2]
    assert native["y"].tolist() == [3, 4]
    assert native["z"].tolist() == [5, 6]
    assert args["dimensions"] is None
    assert wide_id_vars == set()


def test_dimensions_none_without_dataframe_raises():
    args = {"data_frame": None, "dimensions": None}

    with pytest.raises(
        ValueError,
        match="No data were provided. Please provide data either with the "
        "`data_frame` or with the `dimensions` argument.",
    ):
        _process(args, is_pd_like=False, native_namespace=None)


def test_dimensions_array_supports_columns_lists_constants_and_ranges():
    args = {
        "data_frame": _wrap({"x": [1, 2], "y": [3, 4]}),
        "dimensions": ["x", [7, 8], Constant(3), Range()],
    }

    result, wide_id_vars = _process(args)

    native = result.to_native()
    assert native["x"].tolist() == [1, 2]
    assert native["dimensions_1"].tolist() == [7, 8]
    assert native["dimensions_2"].tolist() == [3, 3]
    assert native["dimensions_3"].tolist() == [0, 1]
    assert args["dimensions"] == [
        "x",
        "dimensions_1",
        "dimensions_2",
        "dimensions_3",
    ]
    assert wide_id_vars == {
        "x",
        "dimensions_1",
        "dimensions_2",
        "dimensions_3",
    }


@pytest.mark.parametrize("column_name", ["variable", "value"])
def test_wide_mode_skips_unknown_var_and_value_placeholder_names(column_name):
    args = {"data_frame": _wrap({"x": [1, 2]}), "x": column_name}

    result, wide_id_vars = _process(
        args,
        wide_mode=True,
        var_name="variable",
        value_name="value",
    )

    native = result.to_native()
    assert isinstance(native, pd.DataFrame)
    assert list(native.columns) == []
    assert len(native) == 0
    assert args["x"] == column_name
    assert wide_id_vars == set()


def test_wide_variable_columns_are_not_added_to_wide_id_vars():
    args = {
        "data_frame": _wrap({"x": [1, 2]}),
        "x": "x",
        "wide_variable": [[10, 20], [30, 40]],
    }

    result, wide_id_vars = _process(
        args,
        wide_mode=True,
        var_name="variable",
        value_name="value",
    )

    native = result.to_native()
    assert native["x"].tolist() == [1, 2]
    assert native["wide_variable_0"].tolist() == [10, 20]
    assert native["wide_variable_1"].tolist() == [30, 40]
    assert args["wide_variable"] == ["wide_variable_0", "wide_variable_1"]
    assert wide_id_vars == {"x"}


def test_multiindex_argument_raises_type_error():
    native_frame = pd.DataFrame({"x": [1, 2]})
    args = {
        "data_frame": nw.from_native(native_frame, eager_only=True),
        "x": native_frame.index,
    }

    with pytest.raises(
        TypeError,
        match="Argument 'x' is a pandas MultiIndex. pandas MultiIndex is not supported",
    ):
        _process(args)


def test_dataframe_index_argument_is_escaped_when_name_conflicts_with_column():
    native_frame = pd.DataFrame(
        {"index": [5, 6], "x": [1, 2]},
        index=pd.Index([10, 20]),
    )
    dataframe = nw.from_native(native_frame, eager_only=True)
    args = {
        "data_frame": dataframe,
        "x": nw.maybe_get_index(dataframe),
        "y": "x",
    }

    result, wide_id_vars = _process(args)

    native = result.to_native()
    assert list(native.columns) == ["_index", "x"]
    assert native["_index"].tolist() == [10, 20]
    assert native["x"].tolist() == [1, 2]
    assert args["x"] == "_index"
    assert args["y"] == "x"
    assert wide_id_vars == {"_index", "x"}


def test_named_dataframe_index_uses_its_index_name():
    native_frame = pd.DataFrame(
        {"x": [1, 2]},
        index=pd.Index([10, 20], name="row_id"),
    )
    dataframe = nw.from_native(native_frame, eager_only=True)
    args = {"data_frame": dataframe, "x": nw.maybe_get_index(dataframe)}

    result, wide_id_vars = _process(args)

    native = result.to_native()
    assert list(native.columns) == ["row_id"]
    assert native["row_id"].tolist() == [10, 20]
    assert args["x"] == "row_id"
    assert wide_id_vars == {"row_id"}


def test_series_matching_an_existing_column_is_referenced_by_its_name():
    args = {
        "data_frame": _wrap({"x": [1, 2], "y": [3, 4]}),
