    }

    result, wide_id_vars = _process(args)

    native = result.to_native()
    assert list(native.columns) == ["x"]
    assert native["x"].tolist() == [1, 2]
    assert args["y"] == "x"
    assert wide_id_vars == {"x"}


def test_series_with_matching_name_but_different_values_uses_field_name():
    args = {
