    assert len(native) == 0
    assert wide_id_vars == set()


def test_missing_pandas_for_empty_result_raises_not_implemented(monkeypatch):
    real_import = builtins.__import__

    def import_without_pandas(name, *args, **kwargs):
        if name == "pandas":
            raise ImportError("pandas unavailable")
        return real_import(name, *args, **kwargs)

    monkeypatch.setattr(builtins, "__import__", import_without_pandas)

    with pytest.raises(
        NotImplementedError,
        match="Pandas installation is required.",
    ):
        _process(
            {"data_frame": None},
            is_pd_like=False,
            native_namespace=pd,
        )


def test_missing_pandas_for_inline_data_without_dataframe_raises(monkeypatch):
    real_import = builtins.__import__

    def import_without_pandas(name, *args, **kwargs):
        if name == "pandas":
            raise ImportError("pandas unavailable")
        return real_import(name, *args, **kwargs)

    monkeypatch.setattr(builtins, "__import__", import_without_pandas)

    with pytest.raises(
        NotImplementedError,
        match="Pandas installation is required if no dataframe is provided.",
    ):
        _process(
            {"data_frame": None, "x": [1, 2]},
            is_pd_like=False,
            native_namespace=None,
        )
